  h_graph_mask[source]=1;
  h_graph_visited[source]=1;
  fscanf(fp,"%d",&edge_list_size);
  int id,cost;
  int* h_graph_edges = (int*) malloc(sizeof(int)*edge_list_size);
  for(int i=0; i < edge_list_size ; i++){
    fscanf(fp,"%d",&id);
    fscanf(fp,"%d",&cost);
    h_graph_edges[i] = id;
  }

  if(fp) fclose(fp);    
  // allocate mem for the result on host side
  int  *h_cost = (int*) malloc(sizeof(int)*no_of_nodes);
  int *h_cost_ref = (int*)malloc(sizeof(int)*no_of_nodes);
  for(int i=0;i<no_of_nodes;i++){
    h_cost[i]=-1;
    h_cost_ref[i] = -1;
  }
  h_cost[source]=0;
  h_cost_ref[source]=0;    

  printf("run bfs (#nodes = %d) on device\n", no_of_nodes);
  run_bfs_gpu(no_of_nodes,h_graph_nodes,edge_list_size,h_graph_edges, 
      h_graph_mask, h_updating_graph_mask, h_graph_visited, h_cost);  

  printf("run bfs (#nodes = %d) on host (cpu) \n", no_of_nodes);
  // initalize the memory again
  for(int i = 0; i < no_of_nodes; i++){
    h_graph_mask[i]=0;
    h_updating_graph_mask[i]=0;
    h_graph_visited[i]=0;
  }

  //set the source node as 1 in the mask
  source=0;
  h_graph_mask[source]=1;
  h_graph_visited[source]=1;
  run_bfs_cpu(no_of_nodes,h_graph_nodes,edge_list_size,h_graph_edges, 
      h_graph_mask, h_updating_graph_mask, h_graph_visited, h_cost_ref);

  // verify
  compare_results<int>(h_cost_ref, h_cost, no_of_nodes);

  free(h_graph_nodes);
  free(h_graph_mask);
  free(h_updating_graph_mask);
  free(h_graph_visited);
  free(h_cost);
  free(h_cost_ref);

  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <chrono>
#include <omp.h>
#include "reference.h"

template<int R>
void bilateralFilter(
    const float *__restrict in,
    float *__restrict out,
    int w, 
    int h, 
    float a_square,
    float variance_I,
    float variance_spatial)
{
  #pragma omp target teams distribute parallel for collapse(2) thread_limit(256)
  for (int idy = 0; idy < h; idy++)
    for (int idx = 0; idx < w; idx++) {

      int id = idy*w + idx;
      float I = in[id];
      float res = 0;
      float normalization = 0;

      // window centered at the coordinate (idx, idy)
      #ifdef LOOP_UNROLL
      #pragma unroll
      #endif
      for(int i = -R; i <= R; i++) {
      #ifdef LOOP_UNROLL
      #pragma unroll
      #endif
        for(int j = -R; j <= R; j++) {

          int idk = idx+i;
          int idl = idy+j;

          // mirror edges
          if( idk < 0) idk = -idk;
          if( idl < 0) idl = -idl;
          if( idk > w - 1) idk = w - 1 - i;
          if( idl > h - 1) idl = h - 1 - j;

          int id_w = idl*w + idk;
          float I_w = in[id_w];

          // range kernel for smoothing differences in intensities
          float range = -(I-I_w) * (I-I_w) / (2.f * variance_I);

          // spatial (or domain) kernel for smoothing differences in coordinates
          float spatial = -((idk-idx)*(idk-idx) + (idl-idy)*(idl-idy)) /
            (2.f * variance_spatial);

          // the weight is assigned using the spatial closeness (using the spatial kernel) 
          // and the intensity difference (using the range kernel)
          float weight = a_square * expf(spatial + range);

          normalization += weight;
          res += (I_w * weight);
        }
      }
      out[id] = res/normalization;
    }
}

//
// reference https://en.wikipedia.org/wiki/Bilateral_filter
//
int main(int argc, char *argv[]) {

  if (argc != 6) {
    printf("Usage: %s <image width> <image height> <intensity> <spatial> <repeat>\n",
            argv[0]);
    return 1;
  }

  // image dimensions
  int w = atoi(argv[1]);
  int h = atoi(argv[2]);
  const int img_size = w*h;

  // As the range parameter increases, the bilateral filter gradually 
  // approaches Gaussian convolution more closely because the range 
  // Gaussian widens and flattens, which means that it becomes nearly
  // constant over the intensity interval of the image.
  float variance_I = atof(argv[3]);

  // As the spatial parameter increases, the larger features get smoothened.
  float variance_spatial = atof(argv[4]);

  // square of the height of the curve peak
  float a_square = 0.5f / (variance_I * (float)M_PI);

  int repeat = atoi(argv[5]);

  float *h_src = (float*) malloc (img_size * sizeof(float));
  // host and device results
  float *h_dst = (float*) malloc (img_size * sizeof(float));
  float *r_dst = (float*) malloc (img_size * sizeof(float));

  srand(123);
  for (int i = 0; i < img_size; i++)
    h_src[i] = rand() % 256;

  #pragma omp target data map(to: h_src[0:img_size]) \
                          map(alloc: h_dst[0:img_size])
  {
    auto start = std::chrono::steady_clock::now();

    for (int i = 0; i < repeat; i++)
      bilateralFilter<3>(h_src, h_dst, w, h, a_square, variance_I, variance_spatial);

    auto end = std::chrono::steady_clock::now();
    auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Average kernel execution time (3x3) %f (ms)\n", (time * 1e-6f) / repeat);

    #pragma omp target update from (h_dst[0:img_size])

    // verify
    bool ok = true;
    reference<3>(h_src, r_dst, w, h, a_square, variance_I, variance_spatial);
    for (int i = 0; i < w*h; i++) {
      if (fabsf(r_dst[i] - h_dst[i]) > 1e-3) {
        ok = false;
        break;
      }
    }

    start = std::chrono::steady_clock::now();

    for (int i = 0; i < repeat; i++)
      bilateralFilter<6>(h_src, h_dst, w, h, a_square, variance_I, variance_spatial);

    end = std::chrono::steady_clock::now();
    time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Average kernel execution time (6x6) %f (ms)\n", (time * 1e-6f) / repeat);

    #pragma omp target update from (h_dst[0:img_size])

    reference<6>(h_src, r_dst, w, h, a_square, variance_I, variance_spatial);
    for (int i = 0; i < w*h; i++) {
      if (fabsf(r_dst[i] - h_dst[i]) > 1e-3) {
        ok = false;
        break;
      }
    }

    start = std::chrono::steady_clock::now();

    for (int i = 0; i < repeat; i++)
      bilateralFilter<9>(h_src, h_dst, w, h, a_square, variance_I, variance_spatial);

    end = std::chrono::steady_clock::now();
    time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Average kernel execution time (9x9) %f (ms)\n", (time * 1e-6f) / repeat);

    #pragma omp target update from (h_dst[0:img_size])

    reference<9>(h_src, r_dst, w, h, a_square, variance_I, variance_spatial);
    for (int i = 0; i < w*h; i++) {
      if (fabsf(r_dst[i] - h_dst[i]) > 1e-3) {
        ok = false;
        break;
      }
    }
    printf("%s\n", ok ? "PASS" : "FAIL");
  }

  free(h_dst);
  free(r_dst);
  free(h_src);
  return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <iostream>
#include <chrono>
#include <random>
#include <omp.h>
#include "reference.h"

int main(int argc, char* argv[]) {

  if (argc != 7) {
    printf("Usage: %s <rows> <cols> <cases> <controls> "
           "<threads> <repeat>\n", argv[0]);
    return 1;
  }

  unsigned int rows = atoi(argv[1]);
  unsigned int cols = atoi(argv[2]);
  int ncases = atoi(argv[3]);
  int ncontrols = atoi(argv[4]);
  int nthreads = atoi(argv[5]);
  int repeat = atoi(argv[6]);

  printf("Individuals=%d SNPs=%d cases=%d controls=%d nthreads=%d\n",
         rows,cols,ncases,ncontrols,nthreads);

  size_t size = (size_t)rows * (size_t)cols;
  printf("Size of the data = %lu\n",size);

  // allocate SNP host data 
  unsigned char *dataT = (unsigned char*)malloc(size);
  float* h_results = (float*) malloc(cols * sizeof(float)); 
  float* cpu_results = (float*) malloc(cols * sizeof(float)); 

  if(dataT == NULL || h_results == NULL || cpu_results == NULL) {
    printf("ERROR: Memory for data not allocated.\n");
    if (dataT) free(dataT);
    if (h_results) free(h_results);
    return 1;
  }

  std::mt19937 gen(19937); // mersenne_twister_engin
  std::uniform_int_distribution<> distrib(0, 2);
  for (size_t i = 0; i < size; i++) {
    dataT[i] = distrib(gen) + '0';
  }

  #pragma omp target data map(to: dataT[0:size]) map(from: h_results[0:cols])
  {
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < repeat; i++) {
      #pragma omp target teams distribute parallel for simd thread_limit(nthreads)
      for (int i = 0; i < cols; i++) {
        unsigned char y;
        int m, n;
        unsigned int p = 0;
        int cases[3] = {1,1,1};
        int controls[3] = {1,1,1};
        int tot_cases = 1;
        int tot_controls= 1;
        int total = 1;
        float chisquare = 0.0f;
        float exp[3];        
        float Conexpected[3];        
        float Cexpected[3];
        float numerator1;
        float numerator2;

        // read cases: each thread reads a column of snpdata matrix
        for ( m = 0 ; m < ncases ; m++ ) {
          y = dataT[(size_t)m * (size_t)cols + i];
          if ( y == '0') { cases[0]++; }
          else if ( y == '1') { cases[1]++; }
          else if ( y == '2') { cases[2]++; }
        }

        // read controls: each thread reads a column of snpdata matrix
        for ( n = ncases ; n < ncases + ncontrols ; n++ ) {
          y = dataT[(size_t)n * (size_t)cols + i];
          if ( y == '0' ) { controls[0]++; }
          else if ( y == '1') { controls[1]++; }
          else if ( y == '2') { controls[2]++; }
        }

        for( p = 0 ; p < 3; p++ ) {
          tot_cases += cases[p];
          tot_controls += controls[p];
        }
        total = tot_cases + tot_controls;

        for( p = 0 ; p < 3; p++ ) {
          exp[p] = (float)cases[p] + controls[p]; 
          Cexpected[p] = tot_cases * exp[p] / total;
          Conexpected[p] = tot_controls * exp[p] / total;
          numerator1 = (float)cases[p] - Cexpected[p];
          numerator2 = (float)controls[p] - Conexpected[p];
          chisquare += numerator1 * numerator1 / Cexpected[p] +  numerator2 * numerator2 / Conexpected[p];
        }
        h_results[i] = chisquare;
      }
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Average kernel execution time = %f (s)\n", time * 1e-9f / repeat);
  }

  auto start = std::chrono::high_resolution_clock::now();

  cpu_kernel(rows,cols,ncases,ncontrols,dataT,cpu_results);

  auto end = std::chrono::high_resolution_clock::now();
  auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
  printf("Host execution time = %f (s)\n", time * 1e-9f);

  // verify
  int error = 0;
  for(unsigned int k = 0; k < cols; k++) {
    if (fabs(cpu_results[k] - h_results[k]) > 1e-4) error++;
  }
  printf("%s\n", error ? "FAIL" : "PASS");

  free(dataT);
  free(h_results);
  free(cpu_results);

  return 0;
}

