template <
  int ACTIVE_CHANNELS,
  int NUM_BINS,
  typename PixelType>
double run_smem_atomics(
    PixelType* image,
    int width,
    int height,
    unsigned int* d_hist,
    bool warmup)
{
  enum
  {
    NUM_PARTS = 1024
  };


  //dim3 block(32, 4);
  //dim3 grid(16, 16);
  //int total_blocks = grid.x * grid.y;
  const int total_blocks = 256;

  auto start = std::chrono::steady_clock::now();

  unsigned int *part_hist = (unsigned int *) malloc (total_blocks * NUM_PARTS * sizeof(unsigned int));
#pragma omp target data map (alloc: part_hist[0: total_blocks * NUM_PARTS]) \
  map(to: image[0:width*height]) \
  map(from: d_hist[0:NUM_BINS * ACTIVE_CHANNELS])
  {
#pragma omp target teams num_teams(total_blocks) thread_limit(128)
    {
      unsigned int smem[ACTIVE_CHANNELS * NUM_BINS + 3];
#pragma omp parallel
      {
        int gid = omp_get_team_num() * omp_get_num_threads() + omp_get_thread_num();
        int x = gid % 512;
        int y = gid / 512;
        int nx = 512;
        int ny = 64;
        int t = omp_get_thread_num();
        int nt = 128;
        int g = omp_get_team_num();

        unsigned int* out = part_hist + g*NUM_PARTS;

        for (int i = t; i < ACTIVE_CHANNELS * NUM_BINS + 3; i += nt)
          smem[i] = 0;

#pragma omp barrier

        // process pixels (updates our group's partial histogram in gmem)
        for (int col = x; col < width; col += nx)
        {
          for (int row = y; row < height; row += ny)
          {
            PixelType pixel = image[row * width + col];

            unsigned int bins[ACTIVE_CHANNELS];
            DecodePixel<NUM_BINS>(pixel, bins);

#pragma unroll
            for (int CHANNEL = 0; CHANNEL < ACTIVE_CHANNELS; ++CHANNEL) {
#pragma omp atomic update
              smem[(NUM_BINS * CHANNEL) + bins[CHANNEL] + CHANNEL]++;
            }
          }
        }
#pragma omp barrier

        // store local output to global
        for (int i = t; i < NUM_BINS; i += nt)
        {
#pragma unroll
          for (int CHANNEL = 0; CHANNEL < ACTIVE_CHANNELS; ++CHANNEL)
            out[i + NUM_BINS * CHANNEL] = smem[i + NUM_BINS * CHANNEL + CHANNEL];
        }
      }
    }

#ifdef DEBUG
    printf("partial histogram:\n");
#pragma omp target update from(part_hist[0:total_blocks * NUM_PARTS])
    for (int i = 0; i < total_blocks * NUM_PARTS; i++) {
      printf("%u\n", part_hist[i]);
    }
#endif


#pragma omp target teams distribute parallel for thread_limit(128)
    for (int i = 0; i < ACTIVE_CHANNELS * NUM_BINS; i++)
    {
      unsigned int total = 0;
      for (int j = 0; j < total_blocks; j++)
        total += part_hist[i + NUM_PARTS * j];

      d_hist[i] = total;
    }
  }
  free(part_hist);

  auto end = std::chrono::steady_clock::now();
  std::chrono::duration<double> elapsed_seconds = end-start;
  float elapsed_millis = elapsed_seconds.count()  * 1000;
  return elapsed_millis;
}

#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <chrono>
#include <omp.h>
#include "reference.h"

int main(int argc, char* argv[]) {

  if (argc != 4) {
    printf("Usage: ./%s <query length> <subject length> <repeat>\n", argv[0]);
    return -1;
  }

  const int M = atoi(argv[1]);
  const int N = atoi(argv[2]);
  const int repeat = atoi(argv[3]);

  printf("Query length = %d\n", M);
  printf("Subject length = %d\n", N);

  // host side memory
  float *subject = (float*) malloc (sizeof(float)*N);
  float *lower_bound = (float*) malloc (sizeof(float)*N);
  float *upper_bound = (float*) malloc (sizeof(float)*N);
  float *lb = (float*) malloc (sizeof(float)*(N-M+1));
  float *lb_h = (float*) malloc (sizeof(float)*(N-M+1));
  float *avgs = (float*) malloc (sizeof(float)*(N-M+1));
  float *stds = (float*) malloc (sizeof(float)*(N-M+1));

  srand(123);
  for (int i = 0; i < N; ++i) subject[i] = (float)rand() / (float)RAND_MAX;
  for (int i = 0; i < N-M+1; ++i) avgs[i] = (float)rand() / (float)RAND_MAX;
  for (int i = 0; i < N-M+1; ++i) stds[i] = (float)rand() / (float)RAND_MAX;
  for (int i = 0; i < M; ++i) upper_bound[i] = (float)rand() / (float)RAND_MAX;
  for (int i = 0; i < M; ++i) lower_bound[i] = (float)rand() / (float)RAND_MAX;

  const int blocks = 256;
  const int grids = (N-M+1 + blocks - 1) / blocks;

  #pragma omp target data map (to: subject[0:N], \
                                   avgs[0:N-M+1],\
                                   stds[0:N-M+1],\
                                   lower_bound[0:N],\
                                   upper_bound[0:N])\
                          map(from: lb[0:N-M+1])
  {
    auto start = std::chrono::steady_clock::now();

    for (int i = 0; i < repeat; i++) {
      #pragma omp target teams distribute num_teams(grids) thread_limit(blocks)
      for (int idx = 0; idx < N-M+1; idx++) {
        // obtain statistics
        float residues = 0;
        float avg = avgs[idx];
        float std = stds[idx];

        #pragma omp parallel for reduction(+:residues)
        for (int i = 0; i < M; ++i) {
          // differences to envelopes
          float value = (subject[idx+i] - avg) / std;
          float lower = value - lower_bound[i];
          float upper = value - upper_bound[i];

          // Euclidean distance
          residues += upper*upper*(upper > 0) + lower*lower*(lower < 0);
        }

        lb[idx] = residues;
      }
    }

    auto end = std::chrono::steady_clock::now();
    auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Average kernel execution time: %f (s)\n", (time * 1e-9f) / repeat);
  }

  // verify
  reference(subject, avgs, stds, lb_h, lower_bound, upper_bound, M, N);
  bool ok = true;
  for (int i = 0; i < N-M+1; i++) {
    if (fabs(lb[i] - lb_h[i]) > 1e-2) {
      printf("%d %f %f\n", i, lb[i], lb_h[i]);
      ok = false;
      break;
    }
